mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM sys_user_role ur
    INNER JOIN sys_user u ON u.id = ur.user_id
    WHERE ur.role_id = #{roleId}
      AND ur.deleted_at = 0
      AND u.deleted_at = 0
      AND u.is_super_admin = 1
      AND u.id <> #{operatorId}
)

